<script setup lang="ts">
import { computed,reactive,ref } from 'vue';
import { Head,router } from '@inertiajs/vue3';
import { t } from '../../i18n';
import { formatMoney,setCurrencyPreferences,type CurrencyPreferences } from '../../business-money';
import { useBusinessMutation } from '../../use-business-mutation';
const props=defineProps<{preferences:CurrencyPreferences;currencies:Record<string,[string,number]>}>();
const form=reactive({...props.preferences});const {busy,uncertain,error,submit}=useBusinessMutation();const saved=ref(false);
const example=computed(()=>`${form.symbol} ${Number(props.currencies[form.currency][1])?'1.250,00':'1.250'}`);
function change():void {form.symbol=props.currencies[form.currency][0];}
async function save():Promise<void> {saved.value=false;const v=await submit('/pos/business/settings',{business_name:form.business_name,currency:form.currency,symbol:form.symbol,version:Number(form.version)});if(v){Object.assign(form,v);setCurrencyPreferences(v);saved.value=true;router.reload({only:['workspace_preferences']});}}
</script>
<template><Head :title="t('Business settings')"/><main class="merch-page"><header class="merch-heading"><div><p class="eyebrow">{{ t('Configuration') }}</p><h1>{{ t('Business settings') }}</h1><p>{{ t('Permanent preferences for your business, shared across its outlets and devices.') }}</p></div></header><div class="settings-layout"><nav class="settings-menu"><a class="active" href="/pos/business/settings">{{ t('Business & currency') }}</a><a href="/pos/business/desktop">POS Windows · Kasir &amp; struk</a><a href="/pos/business/access">{{ t('Business access') }}</a><a href="/pos?panel=security#account-security">{{ t('Account & security') }}</a></nav><form class="merch-panel settings-form" @submit.prevent="save"><h2>{{ t('Business & currency') }}</h2><fieldset :disabled="busy||uncertain"><div class="merch-form-grid"><label class="full">{{ t('Business name') }}<input v-model="form.business_name" required maxlength="160"/></label><label>{{ t('Default currency') }}<select v-model="form.currency" :aria-label="t('Default currency')" @change="change"><option v-for="(value,code) in currencies" :key="code" :value="code">{{ code }} · {{ value[0] }}</option></select></label><label>{{ t('Currency symbol') }}<select v-model="form.symbol" :aria-label="t('Currency symbol')"><option :value="currencies[form.currency][0]">{{ currencies[form.currency][0] }}</option><option v-if="form.currency!==currencies[form.currency][0]" :value="form.currency">{{ form.currency }}</option></select></label></div></fieldset><div class="currency-example"><span>{{ t('Display example') }}</span><strong>{{ example }}</strong><small>{{ currencies[form.currency][1] }} {{ t('decimal places') }}</small></div><p class="merch-hint">{{ t('The selected currency is used for new products and new business forms. Existing prices and transactions keep their original currency; no exchange conversion is performed.') }}</p><p v-if="saved" class="merch-success" role="status">{{ t('Settings saved permanently.') }}</p><p v-if="error" class="merch-error" role="alert">{{ error }}</p><footer><button :disabled="busy">{{ t(busy?'Saving…':uncertain?'Retry same request':'Save settings') }}</button></footer></form></div></main></template>
